#include <bits/stdc++.h>
using namespace std;

class MyQueue {
public:
    vector<int> items;                                                              // a plain vector, always kept in FIFO order directly

    void push(int x) {
        items.push_back(x);
    }

    int pop() {
        int front = items.front();
        items.erase(items.begin());                                                   // remove from the FRONT: O(n) shift on a plain vector
        return front;
    }

    int peek() {
        return items.front();
    }

    bool empty() {
        return items.empty();
    }
};

int main() {
    MyQueue q;
    q.push(1);
    q.push(2);
    cout << q.peek() << endl;
    cout << q.pop() << endl;
    cout << boolalpha << q.empty() << endl;
    return 0;
}

