class MyQueue:
    def __init__(self):
        self.in_stack = []                                                  # newly pushed elements land here, newest on top
        self.out_stack = []                                                 # reversed-order elements, oldest on top, ready to pop

    def _transfer_if_needed(self):
        if not self.out_stack:                                             # only refill out_stack once it is COMPLETELY empty
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())                 # reversing in_stack's order into out_stack

    def push(self, x):
        self.in_stack.append(x)

    def pop(self):
        self._transfer_if_needed()
        return self.out_stack.pop()

    def peek(self):
        self._transfer_if_needed()
        return self.out_stack[-1]

    def empty(self):
        return not self.in_stack and not self.out_stack


if __name__ == "__main__":
    q = MyQueue()
    q.push(1)
    q.push(2)
    print(q.peek())
    print(q.pop())
    print(q.empty())

