import java.util.*;

public class Main {
    class MyQueue {
        Deque<Integer> inStack = new ArrayDeque<>();                                  // newly pushed elements land here, newest on top
        Deque<Integer> outStack = new ArrayDeque<>();                                 // reversed-order elements, oldest on top, ready to pop

        void transferIfNeeded() {
            if (outStack.isEmpty()) {                                                    // only refill outStack once it is COMPLETELY empty
                while (!inStack.isEmpty()) {
                    outStack.push(inStack.pop());                                            // reversing inStack's order into outStack
                }
            }
        }

        void push(int x) {
            inStack.push(x);
        }

        int pop() {
            transferIfNeeded();
            return outStack.pop();
        }

        int peek() {
            transferIfNeeded();
            return outStack.peek();
        }

        boolean empty() {
            return inStack.isEmpty() && outStack.isEmpty();
        }
    }

    public static void main(String[] args) {
        MyQueue q = new MyQueue();
        q.push(1);
        q.push(2);
        System.out.println(q.peek());
        System.out.println(q.pop());
        System.out.println(q.empty());
    }
}

