#include <bits/stdc++.h>
using namespace std;

class MyQueue {
public:
    stack<int> inStack;                                                                    // newly pushed elements land here, newest on top
    stack<int> outStack;                                                                    // reversed-order elements, oldest on top, ready to pop

    void transferIfNeeded() {
        if (outStack.empty()) {                                                                // only refill outStack once it is COMPLETELY empty
            while (!inStack.empty()) {
                outStack.push(inStack.top());
                inStack.pop();                                                                    // reversing inStack's order into outStack
            }
        }
    }

    void push(int x) {
        inStack.push(x);
    }

    int pop() {
        transferIfNeeded();
        int front = outStack.top();
        outStack.pop();
        return front;
    }

    int peek() {
        transferIfNeeded();
        return outStack.top();
    }

    bool empty() {
        return inStack.empty() && outStack.empty();
    }
};

int main() {
    MyQueue q;
    q.push(1);
    q.push(2);
    cout << q.peek() << endl;
    cout << q.pop() << endl;
    cout << boolalpha << q.empty() << endl;
    return 0;
}
